SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET transaction_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE TYPE public.gender AS ENUM ('M', 'K'); 

CREATE TABLE public.users (
    user_id SERIAL PRIMARY KEY,
    username character varying(255) NOT NULL UNIQUE,
    email character varying(255) NOT NULL UNIQUE,
    password_hash character varying(255) NOT NULL,
    is_staff boolean DEFAULT false,
    is_active boolean DEFAULT true,
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE public.actors (
    actor_id SERIAL PRIMARY KEY,
    actor_name character varying(255) NOT NULL,
    birth_date date NOT NULL,
    birth_place character varying(255) NOT NULL,
    biography text NOT NULL,
    photo_url character varying(500),
    gender public.gender NOT NULL
);

CREATE TABLE public.directors (
    director_id SERIAL PRIMARY KEY,
    director_name character varying(255) NOT NULL,
    birth_date date NOT NULL,
    birth_place character varying(255) NOT NULL,
    biography text NOT NULL,
    photo_url character varying(500),
    gender public.gender NOT NULL
);

CREATE TABLE public.genres (
    genre_id SERIAL PRIMARY KEY,
    genre_name character varying(255) NOT NULL UNIQUE
);

CREATE TABLE public.movies (
    movie_id SERIAL PRIMARY KEY,
    title character varying(255) NOT NULL,
    release_date date NOT NULL,
    description text NOT NULL,
    poster_url character varying(500),
    duration_minutes integer,
    country character varying(100),
    original_language character varying(50),
    trailer_url character varying(500),
    created_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE public.movie_actors (
    movie_id integer REFERENCES public.movies(movie_id) ON DELETE CASCADE,
    actor_id integer REFERENCES public.actors(actor_id) ON DELETE CASCADE,
    movie_role character varying(255),
    PRIMARY KEY (movie_id, actor_id)
);

CREATE TABLE public.movie_directors (
    movie_id integer REFERENCES public.movies(movie_id) ON DELETE CASCADE,
    director_id integer REFERENCES public.directors(director_id) ON DELETE CASCADE,
    PRIMARY KEY (movie_id, director_id)
);

CREATE TABLE public.movies_genres (
    movie_id integer REFERENCES public.movies(movie_id) ON DELETE CASCADE,
    genre_id integer REFERENCES public.genres(genre_id) ON DELETE CASCADE,
    PRIMARY KEY (movie_id, genre_id)
);

CREATE TABLE public.rentals (
    rental_id SERIAL PRIMARY KEY,
    user_id integer REFERENCES public.users(user_id) ON DELETE CASCADE,
    movie_id integer REFERENCES public.movies(movie_id) ON DELETE CASCADE,
    rental_date timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    due_date timestamp without time zone,
    return_date timestamp without time zone
);



