SELECT setval(pg_get_serial_sequence('public.users', 'user_id'), COALESCE((SELECT MAX(user_id) FROM public.users), 1));
SELECT setval(pg_get_serial_sequence('public.rentals', 'rental_id'), COALESCE((SELECT MAX(rental_id) FROM public.rentals), 1));
SELECT setval(pg_get_serial_sequence('public.actors', 'actor_id'), COALESCE((SELECT MAX(actor_id) FROM public.actors), 1));
SELECT setval(pg_get_serial_sequence('public.directors', 'director_id'), COALESCE((SELECT MAX(director_id) FROM public.directors), 1));
SELECT setval(pg_get_serial_sequence('public.genres', 'genre_id'), COALESCE((SELECT MAX(genre_id) FROM public.genres), 1));
