INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (483, 'Samuel L. Jackson', '1948-12-21', 'Washington, D.C., USA', 'Jest weteranem wśród aktorów. Zanim w latach 90. zyskał popularność występował w teatrze, reklamach telewizyjnych i filmach. Przez długi czas pracował z Negro Ensemble Company i NY Shakespeare Festival, pojawiał się również na Broadwayu. W 1988 r. rozpoczął współpracę z reżyserem Spikem Lee. Okazała się ona bardzo korzystna. Udział w takich filmach jak "Czarny blues" i "Malaria" przyniósł Jacksonowi sławę. Kolejne filmy ugruntowywały jego popularność a w 1995 r. został nominowany do Oscara za rolę w "Pulp Fiction". Samuel Jackson jest aktorem charakterystycznym. Przez wiele lat grywał głównie postaci kryminalistów, którzy z reguły byli w końcowej scenie filmu zabijani. Lata 90. zmieniły jego wizerunek. Obecnie grywa bardzo różne typy bohaterów. W środowisku aktorskim uchodzi za pracoholika. Występuje w kilku filmach kinowych rocznie, nie licząc produkcji telewizyjnych.', 'https://image.tmdb.org/t/p/w500/AiAYAqwpM5xmiFrAIeQvUXDCVvo.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (9, 'Barry Keoghan', '1992-10-18', 'Dublin, Irlandia', 'Irlandzki aktor. Wychowywał się w domach zastępczych, aktorstwo było dla niego ucieczką od trudnej rzeczywistości.', 'BarryKeoghan.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (484, 'Jackie Chan', '1954-04-07', 'Victoria Peak, Hong Kong', 'Jackie Chan (chiński: 成龍; ur. 7 kwietnia 1954), urodzony jako Chan Kong-sang, to aktor, choreograf akcji, reżyser, komik, producent, artysta sztuk walki, scenarzysta, przedsiębiorca, piosenkarz i kaskader. W swoich filmach znany jest z akrobatycznego stylu walki, komiksowego wyczucia czasu, używania improwizowanej broni i innowacyjnych akrobacji. Jackie Chan gra od lat 70. XX wieku i wystąpił w ponad 100 filmach. Chan otrzymał gwiazdy w Alei Gwiazd w Hongkongu i Hollywood Walk of Fame. Jako ikona kultury Chan pojawiał się w różnych piosenkach pop, kreskówkach i grach wideo. Chan jest także gwiazdą Cantopop i Mandopop, wydał wiele albumów i zaśpiewał wiele piosenek przewodnich do filmów, w których zagrał. Chan urodził się 7 kwietnia 1954 r. w Victoria Peak, w byłej kolonii koronnej w Hongkongu, jak Chan Kong-sang (co oznacza „urodzony w Hongkongu”) jako syn Charlesa i Lee-Lee Chanów, uchodźców z chińskiej wojny domowej . Nadano mu przydomek Paopao (chiński: 炮炮, dosłownie oznacza „kula armatnia”), ponieważ był bardzo dużym dzieckiem, ważył 12 funtów, czyli około 5,4 kg. Ponieważ jego rodzice pracowali dla konsula francuskiego w Hongkongu, Chan spędził swoje młode lata na terenie rezydencji konsula w dzielnicy Victoria Peak. Chan uczęszczał do szkoły podstawowej Nah-Hwa na wyspie Hongkong, gdzie nie zdał pierwszej klasy, po czym rodzice wycofali go ze szkoły. W 1960 roku jego ojciec wyemigrował do Canberry w Australii, aby pracować jako główny kucharz w ambasadzie amerykańskiej, a Chan został wysłany do China Drama Academy, pekińskiej szkoły operowej prowadzonej przez mistrza Yu Jim-yuena. Chan rygorystycznie trenował przez następną dekadę, osiągając doskonałe wyniki w sztukach walki i akrobatyce. W końcu stał się częścią Seven Little Fortunes, grupy performerskiej składającej się z najlepszych uczniów szkoły, zyskując pseudonim sceniczny Yuen Lo w hołdzie swojemu mistrzowi. Chan zaprzyjaźnił się z innymi członkami grupy, Sammo Hungiem i Yuenem Biao, a cała trójka była później znana jako Trzej Bracia lub Trzy Smoki. W wieku 17 lat pracował jako kaskader w filmach Bruce''''a Lee Fist of Fury i Enter the Dragon pod pseudonimem Chan Yuen Lung. Swoją pierwszą główną rolę otrzymał jeszcze w tym samym roku w Little Tiger of Canton, który miał limitowaną premierę w Hongkongu w 1973 roku.', 'https://image.tmdb.org/t/p/w500/nraZoTzwJQPHspAVsKfgl3RXKKa.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (485, 'Emily Blunt', '1983-02-23', 'Wandsworth, London, England, UK', 'Emily Blunt urodziła się 23 lutego 1983 roku w Londynie. Jest córką nauczycielki i adwokata. Ma trójkę rodzeństwa. Aktorstwo studiowała w Londynie. Zadebiutowała w Haymarket Theatre, gdzie została wyróżniona za rolę Gwen Cavendish w "The Royal Family". W 2002 roku zagrała Julię w "Romeo i Julii" na prestiżowym festiwalu w Chichester. W 2003 roku sławę przyniosła jej rola Isoldy w serialu "Boudica". Później zagrała w filmie "Lato miłości", gdzie wcieliła się w postać Tamsin - wykształconej, cynicznej i zwodniczej piękności. W 2005 roku spędziła u boku Susan Sarandon i Sama Neilla kilka miesięcy odgrywając rolę podstępnie wywołującej paranoję u innych Mary w filmie "Modliszka". W 2006 roku pojawiła się w Hollywoodzkiej produkcji "Diabeł ubiera się u Prady", gdzie wystąpiła u boku Meryl Streep grając asystentkę tytułowego diabła - Mirandy Priestly. Emily Blunt jest uniwersalną aktorką i wszechstronnie utalentowaną osobą - śpiewa, gra na wiolonczeli i jeździ konno.', 'https://image.tmdb.org/t/p/w500/zpJ7pupuNF3W0zTxm6yioGIoxbd.jpg', 'K');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (14, 'David Jonsson', '1994-08-07', 'Londyn, UK', 'Brytyjski aktor. Wychował się w Peckham w południowym Londynie. Studiował w Royal Academy of Dramatic Art.', 'DavidJonsson.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (7, 'Joaquin Phoenix', '1974-10-28', 'San Juan, Portoryko', 'Amerykański aktor. Pochodzi z artystycznej rodziny, jego rodzeństwo również zajmuje się aktorstwem.', 'JoaquinPhoenix.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (486, 'Peter Stormare', '1953-08-27', 'Arbrå, Gävleborgs län, Sweden', 'Ceniony aktor charakterystyczny. Pochodzi ze Sztokholmu, karierę aktorską rozpoczynał od występów w Królewskim Teatrze Narodowym pod kierunkiem Ingmara Bergmana, grając m.in. w reżyserowanych przez niego spektaklach. Sam wyreżyserował m.in. operę "Don Giovanni". Współpracuje także z telewizją szwedzką i japońską.', 'https://image.tmdb.org/t/p/w500/1rtpuUqBV29jDc1huUhtjGDbEwn.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (487, 'Gary Oldman', '1958-03-21', 'London, England, UK', 'Jest synem spawacza i gospodyni domowej. Dzięki własnej ciężkiej i wytrwałej pracy uzyskał stypendium, które umożliwiło mu rozpoczęcie nauki w brytyjskim Rose Bruford College, który ukończył w 1979 roku. Początki kariery Oldmana są ściśle związane z teatrem. W 1985 roku wystąpił w sztuce "The Pope''''s Wedding", za którą otrzymał nagrody dla najlepszego i najbardziej obiecującego aktora roku. Na dużym ekranie zadebiutował w filmie "Sid i Nancy", wcielając się w postać Sida Viciousa, punk-rockowego muzyka z zespołu Sex Pistols. Za tę rolę otrzymał nagrodę Evening Standard Film dla najlepszego debiutanta. Kolejny występ również był sukcesem. Tym razem w obrazie "Nadstaw uszu" grał rolę Joe Ortona, dramatopisarza homoseksualisty, za którą został nominowany do nagrody Brytyjskiej Akademii Filmu i TV dla najlepszego aktora. Jednak światową popularność zyskał dopiero w 1992 roku występem w filmie "Drakula". Kolejne role udowadniały, że jest aktorem o bardzo dużych możliwościach. Przez krytyków zaczął być porównywany do Roberta De Niro, ponieważ podobnie jak on Oldman "zmienia" się do każdej nowej roli. Jest aktorem o silnej osobowości i temperamencie, a swoją grą potrafi całkowicie pochłonąć uwagę widza.', 'https://image.tmdb.org/t/p/w500/2v9FVVBUrrkW2m3QOcYkuhq9A6o.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (488, 'Tom Hanks', '1956-07-09', 'Concord, California, USA', 'Tom Hanks, właśc. Thomas Jeffrey Hanks (ur. 9 lipca 1956 w Concord) – amerykański aktor, reżyser i producent filmowy. Jest drugim po Spencerze Tracy aktorem, któremu udało się zdobyć statuetkę Oscara dwa razy z rzędu. Jest synem Amosa Mefforda Hanksa (pochodzenia angielsko-walijskiego) i Janet Merilyn Frager (pochodzenia portugalskiego). Miał niezbyt szczęśliwe dzieciństwo, większość czasu spędził w rodzinach zastępczych.  Jego przygoda z aktorstwem zaczęła się w szkole średniej. Nie mogąc dostać roli w przedstawieniu szkolnym, rzucił uczelnię i wyjechał do Cleveland, by wziąć udział w Great Lakes Shakespeare Festival. Udało mu się zaangażować do Riverside Theater, gdzie debiutował w sztuce The Taming of the Shrew (Poskromienie złośnicy). W 1980 został zaangażowany do opowiadającego o parze cwaniaków telewizyjnego serialu komediowego Bosom Buddies. Pierwsze jego role na dużym ekranie to również występy w komediach: Plusku, Wieczorze kawalerskim czy Skarbonce. Przez wiele lat był przez krytyków uznawany za komika (pierwsza nominacja do Oscara za rolę w filmie Duży) i próby obsadzania go w innych rolach nie spotykały się z dobrym przyjęciem. Zmieniło się to dopiero w 1993 po filmie Filadelfia, w którym Tom Hanks pokazał wszystkim, że drzemie w nim również wielki talent dramatyczny. Dowiodła tego także jego wielka kreacja w filmie Forrest Gump. Zarówno za jedną, jak i drugą rolę został nagrodzony Oscarem. W 1996 Hanks zadebiutował jako reżyser i scenarzysta filmem Szaleństwa młodości (That Thing You Do), w którym także wystąpił. W 1999 Tom Hanks otrzymał Złoty Glob oraz czwartą nominację do Nagrody Akademii Filmowej za rolę kapitana Millera w filmie Stevena Spielberga Szeregowiec Ryan. Piątą nominację otrzymał w 2000 za rolę w filmie Cast Away: Poza światem.  Wyprodukował m.in. filmy: Kompania braci (2001), Moje wielkie greckie wesele (2002), Ekspres polarny (2004), Evan Almighty (2007), My Life in Ruins (2008), Mamma Mia! (2008), Pacyfik (2010).  W marcu 2015 wystąpił w teledysku Carly Rae Jepsen „I Really Like You”. Hanks poślubił w 1988 aktorkę Ritę Wilson. Spotkali się trzy lata wcześniej na planie filmu Ochotnicy. Mają dwoje dzieci. Dla żony Hanks zmienił wyznanie z katolickiego na prawosławne. Wcześniej, w latach 1978–1987, Hanks był żonaty z aktorką Samanthą Dillingham (nazwisko sceniczne Samantha Lewes). Z tego małżeństwa ma dwoje dzieci, a syn Samanthy i Toma, Colin, jest również aktorem. Samantha Lewes zmarła w 2002 na raka kości.  Spokrewniony z szesnastym prezydentem USA Abrahamem Lincolnem. Wspólnym przodkiem Lincolna i Toma Hanksa był John Hanks, ur. w 1687, który był pradziadkiem matki Abrahama Lincolna - Nancy Hanks. Od dzieciństwa był bliskim przyjacielem Bruce’a Springsteena.', 'https://image.tmdb.org/t/p/w500/oFvZoKI6lvU03n4YoNGAll9rkas.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (489, 'Christine Bermas', '2001-08-30', 'Manila, Philippines', 'Christine Bermas, wszechstronna filipińska aktorka i modelka, zyskała uznanie w branży rozrywkowej dzięki współpracy z agencją Viva Artist Agency (VAA). W czasie pandemii seksowna aktorka stała się powszechnie znana i jest bardzo wdzięczna VIVA oraz swojemu menadżerowi Lenowi Carrillo. Christine rozpoczęła karierę w żeńskiej grupie wokalno-tanecznej Belladonnas.  Jej różnorodne role w filmach takich jak Bedspacer (2024), Beyond the Sky (2022), Batang Quiapo (2023), Relyebo (2022), Island of Desire (2022) i Scorpio Nights 3 (2022), zdobył uznanie krytyków i wierne grono fanów, wykazując się umiejętnością wcielania się w role z głębią i autentycznością. Współpraca Bermas z Vivamax dała mu platformę do zaprezentowania swojego talentu w wielu gatunkach, urzekając publiczność swoją wszechstronnością i charyzmą.  Spotyka się z Nico Locco. Pracuje w tej samej branży. Christine przyznała również, że nigdy nie złamano jej serca, ponieważ Nico był jej pierwszym chłopakiem.', 'https://image.tmdb.org/t/p/w500/7KPne6ysCl1ffWqYnDUWfye6vFP.jpg', 'K');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (3, 'Timothée Chalamet', '1995-12-27', 'Nowy Jork, USA', 'Amerykańsko-francuski aktor. Jego matka jest Amerykanką pochodzenia żydowskiego, a ojciec Francuzem.', 'TimotheeChalamet.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (722, 'Benedict Wong', '1971-07-03', 'Eccles, Salford, Greater Manchester, England, UK', 'Benedict Wong umiejętności aktorskie zdobywał na dwuletnim kursie w Salford City College. Debiutował w 1992 roku rolą Le Van Donga w serialu telewizyjnym pt.: Screenplay. W 2003 roku był nominowany do British Independent Film Award za kreację Guo Yi w produkcji pt.: Dirty Pretty Things.', 'https://image.tmdb.org/t/p/w500/yYfLyrC2CE6vBWSJfkpuVKL2POM.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (10, 'Aulii Cravalho', '2000-11-22', 'Kohala, USA', 'Hawajska aktorka i piosenkarka. Została odkryta podczas przesłuchania szkolnego.', 'AuliCravalho.jpg', 'K');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (6, 'Anne Hathaway', '1982-11-12', 'Brooklyn, USA', 'Amerykańska aktorka. Jej matka była aktorką teatralną, co wpłynęło na jej wybór kariery.', 'actor_6_20250521212836_Anne_Hathaway_at_Berlinale_2023_close-up.jpg', 'K');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (4, 'Zendaya', '1996-09-01', 'Oakland, USA', 'Amerykańska aktorka i piosenkarka. Urodziła się w rodzinie nauczycieli, karierę rozpoczęła jako dziecko.', 'Zendaya.jpg', 'K');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (490, 'Sam Neill', '1947-09-14', 'Omagh, County Tyrone, Northern Ireland, UK', 'Sam Neill, urodzony w 14 września 1947 roku, w Irlandii Północnej, dzieciństwo spędził w Nowej Zelandii. Pierwsze kroki w kierunku zawodu aktora skierowały go na deski teatru, udzielał się także w charakterze realizatora filmów dokumentalnych. W świecie filmu zadebiutował w 1977 roku w dramacie "Śpiące psy", lecz prawdziwe uznanie przyniosła mu dopiero rola Harry''''go Beechama w "Mojej wspaniałej karierze" z 1979 roku. Szerszej publiczności dał się poznać, przyjmując główna rolę w trzeciej części kultowego "Omena". W 1981 roku przeprowadził się do Londynu. W tym czasie zagrał w kilku europejskich produkcjach, min: "Posession" (1981) Andrzeja Żuławskiego, "Z dalekiego kraju" Krzysztofa Zanussiego. W 1990 roku otrzymał jedną z głównych ról obok Seana Connery''''go w filmie "Polowanie na Czerwony Październik". W 1993 Steven Spielberg zaangażował go do superprodukcji "Park Jurajski", gdzie jako paleontolog dr Alan Grant musiał stawić czoło zabójczym dinozaurom. Po ogromnym sukcesie pierwszej części, Neill wziął udział także w kontynuacji obrazu. W 1998 roku Robert Redford obsadził go w roli Roberta MacLeana w swoim filmie "Zaklinacz koni". W tym czasie również pracował nad telewizyjną produkcją fantasy - "Merlin". Rola legendarnego czarodzieja przyniosła mu nominacje do nagrody Emmy i Złotego Globu. W "Człowieku przyszłości" z 1999 roku zagrał u boku Robina Williamsa. Sam Neill do tej pory zagrał w wielu bardzo różnorodnych produkcjach, zarówno w komercyjnych jak i niezależnych, co umożliwiło mu zdobycie statusu aktora nad wyraz charakterystycznego i wszechstronnego.', 'https://image.tmdb.org/t/p/w500/iIfuxalf37xUayuGyK0zG7z6WEZ.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (491, 'Jenna Ortega', '2002-09-27', 'Coachella Valley, Palm Desert, California, USA', 'Jenna Marie Ortega (ur. 27 września 2002 w Nowym Jorku) – amerykańska aktorka. Rozpoczęła karierę jako aktorka dziecięca, otrzymując uznanie za rolę młodej Jane w serialu komediowym "The CW Jane the Virgin" (2014–2019). Przełomem w niej była rola Harley Diaz w serialu Disney Channel "Rodzinka od środka" (2016–2018), za który zdobyła nagrodę Imagen Award. W 2019 roku zagrała Ellie Alves w drugim sezonie thrillera platformy Netflix "You" oraz w filmie familijnym "Dzień na tak" (2021).  Ortega otrzymała pochwały krytyków za występ w dramacie dla nastolatków "Następstwa" (2021), a następnie zagrała w slasherach "X" i "Krzyk" z 2022 roku, zostając uznaną za królową krzyku. Zagrała Wednesday Addams w horrorze platformy Netflix "Wednesday" (2022), za który otrzymała nominację do Złotego Globu.', 'https://image.tmdb.org/t/p/w500/cV4x7jNmsGLdKZn5I6xVF3Ltnmg.jpg', 'K');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (492, 'Jason Statham', '1967-07-26', 'Shirebrook, Derbyshire, England, UK', 'Jason Statham urodził się w 1972 roku w  Londynie. W roku 1992 był członkiem Reprezentacji Olimpijskiej Wielkiej Brytanii. Szansa do wejścia w świat rozrywki nadeszła dla niego kiedy jeden z agentów umieścił go w reklamie dla French Connection. Póżniej Statham zagrał w filmie "Porachunki" rolę Bacon. Zagrał również w m.in. "Przekręt" oraz "Transporter". Jego kariera filmowa dopiero się rozwija.', 'https://image.tmdb.org/t/p/w500/whNwkEQYWLFJA8ij0WyOOAD5xhQ.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (516, 'Nathan Fillion', '1971-03-27', 'Edmonton, Alberta, Canada', 'Nathan Craig Fillion (ur. 27 marca 1971 w Edmonton w prowincji Alberta) – kanadyjski aktor, najlepiej znany jako kapitan Malcolm „Mal” Reynolds z serialu Fox Firefly i filmu Jossa Whedona Serenity (2005), a także jako Richard Castle w serialu kryminalnym stacji ABC Castle. Uczęszczał do Holy Trinity Catholic High School, na Concordia University of Alberta i Uniwersytet Alberty.', 'https://image.tmdb.org/t/p/w500/aW6vCxkUZtwb6iH2Wf88Uq0XNVv.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (80, 'Paul Mescal', '1996-02-02', 'Maynooth, Irlandia', 'Irlandzki aktor teatralny i telewizyjny. Zyskał sławę dzięki roli w serialu „Normal People”.', 'https://upload.wikimedia.org/wikipedia/commons/4/46/Paul_Mescal_at_the_Toronto_International_Film_Festival_in_2025_2_%28cropped_2%29.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (45, 'Pedro Pascal', '1975-04-02', 'Santiago, Chile', 'Chileńsko‑amerykański aktor. Jako niemowlę wraz z rodziną uciekł z Chile przed dyktaturą Pinocheta, wychował się w Danii i Teksasie, studiował aktorstwo w Nowym Jorku.', 'PedroPascal.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (46, 'Michael Fassbender', '1977-04-02', 'Heidelberg, Niemcy', 'Niemiecko‑irlandzki aktor. Dorastał w Irlandii, studiował psychologię, zanim zaczął aktorstwo. Ma artystyczne korzenie i dualne obywatelstwo.', 'MichaelFassbender.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (47, 'Daniel Brühl', '1978-06-16', 'Barcelona, Hiszpania', 'Niemiecko‑hiszpański aktor. Urodzony w Hiszpanii, dorastał w Niemczech, studiował w Berlinie i prowadzi działalność filmową w obu krajach.', 'DanielBruhl.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (48, 'Chris Hemsworth', '1983-08-11', 'Melbourne, Australia', 'Australijski aktor. Wychowywał się w rodzinie nauczycieli i sportowców, pracował jako ratownik plażowy zanim zaczął karierę filmową.', 'ChrisHemsworth.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (49, 'Eddie Redmayne', '1982-01-06', 'Londyn, UK', 'Brytyjski aktor. Ukończył Eton i Cambridge, studiował nauki przyrodnicze, zanim zajął się aktorstwem teatralnym.', 'EddieRedmayne.jpg', 'M');
INSERT INTO public.actors (actor_id, actor_name, birth_date, birth_place, biography, photo_url, gender) VALUES (50, 'Emma Watson', '1990-04-15', 'Paryż, Francja', 'Angielsko‑francuska aktorka. Urodzona w Paryżu, dorastała w Anglii, studiowała literaturę angielską na Oxfordzie.', 'EmmaWatson.jpg', 'K');
