INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (27, 'Don Hall', '1969-03-08', 'Glenwood, Iowa, USA', 'Donald Lee Hall urodził się 8 marca 1969 roku w Glenwood w stanie Iowa. Jest absolwentem University of Iowa z tytułem licencjata sztuk pięknych w rysunku i malarstwie. Pracował jako reżyser animacji w Walt Disney Animation Studios, gdzie wyreżyserował "Kubuś i przyjaciele", "Big Hero 6" (za który zdobył Oscara), "Raya i ostatni smok" oraz "Dziwny świat". W czerwcu 2024 roku dołączył do Skydance Animation, aby rozwijać i produkować oryginalny film animowany.', 'director_27_DonHall.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (23, 'Drew Hancock', '1979-07-09', 'Omaha, Nebraska, USA', 'Drew Hancock to scenarzysta i reżyser, znany z takich produkcji jak "Companion" (2025), "My Dead Ex" (2018) i "Suburgatory" (2011).', 'director_23_DrewHancock.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (25, 'Ron Clements', '1953-04-25', 'Sioux City, Iowa, USA', 'Ronald Francis Clements urodził się 25 kwietnia 1953 roku w Sioux City w stanie Iowa. Rozpoczął karierę jako animator w Hanna-Barbera, zanim dołączył do Disneya. Przez lata współpracował z Johnem Muskerem, tworząc klasyczne animacje Disneya. Clements był nominowany do Oscarów za filmy "Planeta skarbów" i "Księżniczka i żaba".', 'director_25_RonClements.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (99, 'Paul Verhoeven', '1938-07-18', 'Amsterdam, Noord-Holland, Netherlands', '', 'https://image.tmdb.org/t/p/w500/2TQvrRCtS7GD0EEgODwfNMmkMbG.jpg', 'M');
