INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (234, 'Jennifer Kent', '1969-03-05', 'Brisbane, Australia', '', 'https://image.tmdb.org/t/p/w500/neV1Pc9Ed051WmQ4jahjEHuIbRg.jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (235, 'Ana Lily Amirpour', '1976-07-25', 'Margate, England, UK', '', 'https://image.tmdb.org/t/p/w500/bay1UyEh7oRwhW5ZIXvzpc33pXe.jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (26, 'Chris Williams', '1968-12-19', 'Missouri, USA', 'Chris Williams urodził się 19 grudnia 1968 roku w Missouri, ale dorastał w Kitchener w Ontario w Kanadzie. Ukończył University of Waterloo oraz program animacji w Sheridan College. Pracował dla Walt Disney Animation Studios w latach 1998-2018, gdzie wyreżyserował "Bolt" i "Big Hero 6" (za który otrzymał Oscara), a także współreżyserował "Moana". W 2018 roku przeniósł się do Netflix Animation, gdzie wyreżyserował "The Sea Beast".', 'director_26_ChrisWilliams.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (18, 'Denis Villeneuve', '1967-10-03', 'Trois-Rivières, Québec, Canada', 'Denis Villeneuve to francusko-kanadyjski reżyser i scenarzysta. Karierę rozpoczął w National Film Board of Canada. Zyskał uznanie dzięki filmom "Polytechnique" i "Incendies", a później stał się jednym z najbardziej cenionych reżyserów w Hollywood, tworząc takie filmy jak "Prisoners", "Sicario" i "Arrival".', 'director_18_DenisVilleneuve.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (107, 'Joss Whedon', '1964-06-23', 'New York City, New York, USA', '', 'https://image.tmdb.org/t/p/w500/mVvpZnKYKSCtkOQixQnOonV5kv3.jpg', 'M');
