INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (126, 'Steve McQueen', '1969-10-09', 'London, England, UK', '', 'https://image.tmdb.org/t/p/w500/if4tLIZJ0EJtyhlJaSzSwMQU5Yz.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (50, 'Martin Scorsese', '1942-11-17', 'Queens, Nowy Jork, USA', 'Amerykański reżyser, producent i scenarzysta. Klasyk kina amerykańskiego, twórca "Taksówkarza" i "Kasyna".', 'https://upload.wikimedia.org/wikipedia/commons/5/54/Martin_Scorsese-68749.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (42, 'Greta Gerwig', '1983-08-04', 'Sacramento, USA', 'Greta Celeste Gerwig to amerykańska reżyserka, scenarzystka i aktorka. Na początku kariery współpracowała przy kinie niezależnym, zdobywając uznanie za filmy "Lady Bird" i "Małe kobietki", a w 2023 roku wyreżyserowała światowy hit "Barbie".', 'GretaGerwig.jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (20, 'Todd Phillips', '1970-12-20', 'New York City, NY, USA', 'Todd Phillips to reżyser, producent i scenarzysta, znany z serii filmów "Kac Vegas" oraz takich produkcji jak "Old School" i "Starsky i Hutch". Porzucił studia filmowe na New York University, aby ukończyć dokument "Hated: GG Allin and the Murder Junkies". Współtworzył scenariusz do "Jokera", który zdobył uznanie krytyków.', 'director_20_ToddPhillips.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (64, 'Tyler Gillett', '1982-04-06', 'Flagstaff, USA', '', '20250901164035_362043.1.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (53, 'Agnieszka Holland', '1948-11-28', 'Warszawa, Polska', 'Polska reżyserka filmowa i scenarzystka, autorka filmów "W ciemności", "Europa, Europa" oraz "Pokot".', 'director_53_asdasd.jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (43, 'Alfonso Cuarón', '1961-11-28', 'Meksyk, Meksyk', 'Meksykański reżyser, scenarzysta i producent. Zdobywca Oscara za "Grawitację" i "Romę". Studiował na Narodowym Uniwersytecie Autonomicznym Meksyku.', 'director_43_asadasd.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (52, 'Ang Lee', '1954-10-23', 'Pingtung, Tajwan', 'Tajwański reżyser pracujący głównie w USA i Wielkiej Brytanii. Dwukrotny zdobywca Oscara za "Tajemnicę Brokeback Mountain" i "Życie Pi".', 'director_52_2016_NAB_Show''s_The_Future_of_Cinema_Conference,_produced_in_partnership_with_SMPTE_(26717112630)_(cropped).jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (46, 'Ava DuVernay', '1972-08-24', 'Long Beach, Kalifornia, USA', 'Amerykańska reżyserka i producentka. Znana z filmów "Selma" oraz "A Wrinkle in Time". Wcześniej pracowała jako publicystka.', 'director_46_Ava_DuVernay_2015.jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (61, 'Barry Jenkins', '1979-11-19', 'Miami, USA', 'Amerykański reżyser i scenarzysta. Największy sukces odniósł filmem "Moonlight", który zdobył Oscara za najlepszy film.', 'director_61_asdasd.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (58, 'Gina Prince-Bythewood', '1969-06-10', 'Los Angeles, USA', 'Amerykańska reżyserka i scenarzystka. Przełomem w jej karierze był film "Love & Basketball", znana także dzięki docenianemu thrillerowi "The Old Guard".', 'director_58_MV5BMjhlMjVhNmUtMzRjMC00MTIwLTk0M2ItZDliZmZlYzRlZmE3XkEyXkFqcGc@._V1_.jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (59, 'James Cameron', '1954-08-16', 'Kapuskasing, Kanada', 'Kanadyjski reżyser, producent i scenarzysta. Zdobywca Oscara za "Titanica", znany też z serii "Terminator" oraz "Avatar".', 'director_59_asdasdasd.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (60, 'Jane Campion', '1954-04-30', 'Wellington, Nowa Zelandia', 'Nowozelandzka reżyserka i scenarzystka, laureatka Złotej Palmy za "Fortepian" i Oscara za "Psie pazury".', 'director_60_asdasd.jfif', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (54, 'Jordan Peele', '1979-02-21', 'Nowy Jork, USA', 'Amerykański reżyser, scenarzysta i aktor. Zasłynął filmem "Uciekaj!", który łączy horror z satyrą społeczną, a kolejne produkcje ("To my", "Nie!") potwierdziły jego status innowatora nowoczesnego kina grozy.', 'director_54_Jordan_Peele_Peabody_2014_(cropped).jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (44, 'Kathryn Bigelow', '1951-11-27', 'San Carlos, Kalifornia, USA', 'Amerykańska reżyserka oraz producentka. Jako pierwsza kobieta zdobyła Oscara za reżyserię filmu "The Hurt Locker". W młodości studiowała malarstwo.', 'director_44_asdad.jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (63, 'Lone Scherfig', '1959-05-02', 'Kopenhaga, Dania', 'Duńska reżyserka i scenarzystka, znana z "Był sobie chłopiec", "Italian for Beginners" i "Edukacji". Pracuje w europejskim i brytyjskim kinie.', 'director_63_afsdfdsf.jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (55, 'Luc Besson', '1959-03-18', 'Paryż, Francja', 'Francuski reżyser, scenarzysta i producent. Twórca takich filmów jak "Leon zawodowiec", "Piąty element" i "Valerian". Wielki entuzjasta kina akcji i science fiction.', 'director_55_Luc_Besson_Cannes_2016.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (62, 'Park Chan-wook', '1963-08-23', 'Seul, Korea Południowa', 'Koreański reżyser, scenarzysta i producent. Zyskał globalne uznanie dzięki thrillerom "Oldboy", "Służąca" i "Stoker".', 'director_62_asdasd.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (48, 'Taika Waititi', '1975-08-16', 'Wellington, Nowa Zelandia', 'Nowozelandzki reżyser, aktor i scenarzysta pochodzenia maoryskiego. Znany z filmów "Jojo Rabbit", "Thor: Ragnarok" i "Co robimy w ukryciu".', 'director_48_aasdad.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (49, 'Patty Jenkins', '1971-07-24', 'Victorville, Kalifornia, USA', 'Amerykańska reżyserka i scenarzystka. Znana z filmów "Monster" i "Wonder Woman". Studiowała malarstwo na Cooper Union.', 'director_49_Patty_Jenkins_at_the_2018_Comic-Con_International.jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (57, 'Wes Anderson', '1969-05-01', 'Houston, USA', 'Amerykański reżyser, znany z charakterystycznego stylu wizualnego, symetrii i ironii. Autor m.in. "Grand Budapest Hotel", "Moonrise Kingdom" i "Rushmore".', 'director_57_Wes_Anderson-20140206-85.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (47, 'Paweł Pawlikowski', '1957-09-15', 'Warszawa, Polska', 'Polski reżyser i scenarzysta. Laureat Oscara za film "Ida". Pracował głównie w Wielkiej Brytanii.', 'director_47_472175_1.3.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (56, 'Pedro Almodóvar', '1949-09-25', 'Calzada de Calatrava, Hiszpania', 'Hiszpański reżyser i scenarzysta, mistrz kina autorskiego. Laureat Oscara, znany z filmów "Wszystko o mojej matce" i "Porozmawiaj z nią".', 'director_56_Pedro_Almodóvar-69720_(cropped).jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (51, 'Sofia Coppola', '1971-05-14', 'Nowy Jork, USA', 'Amerykańska reżyserka, scenarzystka i producentka. Uhonorowana Oscarem za scenariusz "Między słowami". Córka Francisa Forda Coppoli.', 'director_51_SofiaCoppPicCen081223_(6_of_22)_(53388050173)_(cropped).jpg', 'K');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (45, 'Steven Spielberg', '1946-12-18', 'Cincinnati, Ohio, USA', 'Jeden z najbardziej znanych reżyserów i producentów filmowych na świecie. Zdobywca wielu Oscarów, autor tak kultowych filmów jak "E.T.", "Lista Schindlera" i "Park Jurajski".', 'director_45_MKr25402_Steven_Spielberg_(Berlinale_2023)_(3x4_cropped).jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (127, 'Michel Gondry', '1963-05-08', 'Versailles, France', '', 'https://image.tmdb.org/t/p/w500/1IAnVsl8JgHpUirBXpsbLlWyS1y.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (128, 'Roger Spottiswoode', '1945-01-05', 'Ottawa, Ontario, Canada', '', 'https://image.tmdb.org/t/p/w500/ofSwHS4FtNtKO70LHqXdOgU67iP.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (65, 'Quentin Tarantino', '1963-03-27', 'Knoxville, Tennessee, USA', 'Gdy w 1992 roku na ekrany wszedł film "Wściekłe psy", wyreżyserowany przez nikomu nieznanego debiutanta Quentina Tarantino, krytycy chórem krzyknęli, że oto mamy do czynienia z narodzinami prawdziwego talentu. Kiedy dwa lata później powstał obraz pt. "Pulp Fiction", zachwyt przeszedł wszelkie granice. Film zdobył Złotą Palmę w Cannes, Oscara za scenariusz i został okrzyknięty, podobnie jak jego twórca, kultowym. Tygodnik "Variety" twierdził, że Tarantino jest pierwszym z nowej generacji reżyserów - artystów, którzy swojego fachu będą uczyli się nie w szkołach, ale oglądając film na wideo. Powoływali się na fakt, iż Quentin, będąc maniakiem kina, pięć lat przepracował w wypożyczalni kaset, gdzie miał łatwy dostęp do filmów i mógł je oglądać też w godzinach pracy. Codziennie pochłaniał po kilka obrazów, od niskobudżetowych produkcji rodem z Hongkongu po dzieła francuskiej "nowej fali". Była to jego szkoła filmowa. Realizacją "Wściekłych psów" udało mu się zainteresować Harveya Keitela, który nie dość, że zwiększył budżet filmu z 35 tysięcy dolarów do 1,5 miliona, to jeszcze przekonał do zagrania w nim takich aktorów jak Tim Roth czy Michael Madsen. Obecnie Quentin Tarantino jest prawdopodobnie jednym z najchętniej oglądanych i najczęściej dyskutowanych reżyserów naszych czasów. Przez wielu krytyków przedstawiany jest jako wzorowy przykład twórcy postmodernistycznego.', 'https://image.tmdb.org/t/p/w500/1gjcpAa99FAOWGnrUvHEXXsRs7o.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (66, 'Peter Jackson', '1961-10-31', 'Pukerua Bay, North Island, New Zealand', 'Peter Jackson (ur. 31 października 1961 w Pukerua Bay) – nowozelandzki reżyser, scenarzysta oraz producent filmowy. Najbardziej znany z filmowej trylogii Władca Pierścieni.', 'https://image.tmdb.org/t/p/w500/bNc908d59Ba8VDNr4eCcm4G1cR.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (67, 'Roman Polanski', '1933-08-18', 'Paris, France', 'Reżyser filmowy i teatralny, scenarzysta, aktor, producent filmowy. W 1957 roku ukończył Wydział Reżyserii PWSF w Łodzi. W 1963 wyemigrował na Zachód, gdzie zdobył ogromną popularność tworząc wiele wybitnych i popularnych filmów w USA, Francji i Wielkiej Brytanii. [Internetowa Baza Filmu Polskiego filmpolski.pl].', 'https://image.tmdb.org/t/p/w500/yHwHSXdZatkoLgIjPeW14GKlrZs.jpg', 'M');
INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (68, 'David Yates', '1963-10-08', 'St. Helens, Merseyside, England, UK', 'Pracował w Cre8 Studios w Regent Circus, Swindon jako pomocnik. Reżyserskiego fachu uczył się w National Film and Television School w Beaconsfield. Po tym, jak przyciągnął uwagę i uznanie w świecie za reżyserię szeroko nagradzanych seriali dla brytyjskiej telewizji, włączając w to nominację do nagrody BAFTA za jego "Rank", Yates produktywnie zajmował się reżyserią uznanych przez BAFTA seriali i filmów telewizyjnych dla BBC: "The Young Visiters", "The Way We Live Now", "The Sins" oraz wielokrotnie nagradzanego miniserialu "State of Play".', 'https://image.tmdb.org/t/p/w500/hAHOxR0NK4cZDumqNIpDoEdGVAh.jpg', 'M');
