INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (364, 'Krzysztof Tchórzewski', '1950-07-26', 'Kielce, świętokrzyskie, Polska', 'Reżyser. W 1979 roku ukończył Wydział Reżyserii PWSFTviT w Łodzi. Ukończył historię sztuki na Uniwersytecie Warszawskim (1973). W 1991 roku został przewodniczącym Sekretariatu Kultury NSZZ "Solidarność". W latach 2003-07 członek Zarządu Głównego Stowarzyszenia Filmowców Polskich, od roku 2011 zastępca członka zarządu.  Syn wybitnego malarza i profesora ASP Jerzego Tchórzewskiego. [FilmPolski]', 'https://image.tmdb.org/t/p/w500/yM4rnc2KWyoIE0bXXaMziqxIwnB.jpg', 'M');
