INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (370, 'Simon J. Smith', '1968-09-16', 'Watford, England, UK', 'Brytyjski animator, reżyser i aktor głosowy. Najbardziej znany jest ze swojej pracy w DreamWorks Animation. Smith dołączył do PDI/DreamWorks w 1997 roku jako szef działu filmów fabularnych firmy. Weteran animacji CG z prawie 35-letnim doświadczeniem, Smith nadzorował dział layoutu pierwszego filmu animowanego PDI / DreamWorks Antz, pełniąc funkcję szefa układu w Shreku.', 'https://image.tmdb.org/t/p/w500/puCP7MQ8Gm9aKGcQiOcLiKIKcpJ.jpg', 'M');
