INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (473, 'Jerzy Hoffman', '1932-03-15', 'Kraków, małopolskie, Polska', 'Reżyser filmów fabularnych i dokumentalnych. Urodził się w rodzinie lekarskiej. W roku 1940 został wywieziony na Syberię. Do Polski wrócił po zakończeniu wojny. Maturę zdał w Bydgoszczy w roku 1950. Jako reżyser debiutował w roku 1955 wspólnie z Edwardem Skórzewskim, z którym przez kolejne lata tworzył tandem reżyserski. Zrealizowali wspólnie 27 filmów dokumentalnych. W latach 1983-87 wiceprezes ZG SFP. W latach 1987-89 członek Komitetu Kinematografii. Kierownik artystyczny Zespołu Filmowego "Zodiak" (1980-97). Od 1997 współwłaściciel spółki "Zodiak Jerzy Hoffman Production". Członek Polskiej Akademii Filmowej. [Internetowa Baza Filmu Polskiego filmpolski.pl]', 'https://image.tmdb.org/t/p/w500/29iNh2JlmeF1opRMiZiBlABJXiM.jpg', 'M');
