INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (489, 'Emma Tammi', '1982-02-26', 'New York City, New York, USA', 'Emma Tammi (ur. 26 lutego 1982) to producentka, reżyserka i scenarzystka ze Stanów Zjednoczonych. Jest reżyserką Pięciu koszmarnych nocy i jest znana głównie z filmów Demony prerii, Into the Dark i The Left Right Game.', 'https://image.tmdb.org/t/p/w500/oLpOXrGfZZ05bmhm2Xl8T2ZDEk3.jpg', 'K');
