INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (498, 'Janusz Majewski', '1931-08-05', 'Lwów, Polska (obecnie Ukraina)', 'Reżyser. Ukończył architekturę na Politechnice Krakowskiej (1955). Karierę rozpoczynał jako autor scenografii filmowych. W latach 1983-90 prezes Zarządu Głównego SFP, od roku 2006 Honorowy Prezes Stowarzyszenia. W latach 1987-91 członek Komitetu Kinematografii. Członek Polskiej Akademii Filmowej. Od roku 2012 rektor Warszawskiej Szkoły Filmowej.  Wspólnie z Jerzym Mierzejewskim używał pseudonimu J. G. Sandbarmay.', 'https://image.tmdb.org/t/p/w500/pIImEyI5sTdhpUcc8n82uO66nY1.jpg', 'M');
