INSERT INTO public.directors (director_id, director_name, birth_date, birth_place, biography, photo_url, gender) VALUES (504, 'Christopher Nolan', '1970-07-30', 'Londyn, Wielka Brytania', 'Sir Christopher Edward Nolan, CBE – brytyjski reżyser, scenarzysta i producent filmowy. Jest jednym z najbardziej dochodowych reżyserów w historii i jednym z najwyżej cenionych filmowców XXI wieku', '20250928222032_asdasd.webp', 'M');
